namespace {
  // Timeliness classification: ratio of access latency to avg miss latency
  // Make "timely" stricter so we favor very early prefetches, and slightly
  // tighten the late cutoff to penalize delayed observations.
  constexpr double TIMELY_THRESHOLD = 0.30;  // below this → timely prefetch
  constexpr double LATE_THRESHOLD   = 1.20;  // above this → late prefetch

  // Weights in composite_score()
  // Increase coverage importance modestly, and emphasize timeliness so we
  // prefer early+reliable deltas; keep a firm late penalty to avoid pollution.
  constexpr double COVERAGE_WEIGHT    = 1.4;
  constexpr double TIMELINESS_WEIGHT  = 2.2;
  constexpr double ACCURACY_WEIGHT    = 1.6;

  // How many deltas to prefetch per access
  // Reduce degree to limit bandwidth/pollution and rely on better scoring.
  constexpr int PREFETCH_DEGREE = 2;

  // Per-PC history buffer depth (capped at pc_entry::history array size = 16)
  // Keep moderate history to stabilize confidence while focusing on recent behavior.
  constexpr int HISTORY_DEPTH = 12;

  // Minimum observations of a delta before trusting it
  // Keep conservative to avoid chasing noise.
  constexpr int MIN_CONFIDENCE = 4;

  // Maximum absolute delta value to track
  // Tighten to focus on nearer deltas which tend to be more accurate.
  constexpr int MAX_DELTA = 16;

  // Throttle fill-level prefetches when MSHR is this full
  // Slightly relaxed to allow useful progress but still prevent overload.
  constexpr double MSHR_THRESHOLD = 0.45;
} // namespace

double berti::composite_score(int timely, int late, int total)
{
  if (total == 0)
    return 0.0;

  // Basic ratios
  double timely_ratio = static_cast<double>(timely) / total;
  double late_ratio   = static_cast<double>(late) / total;
  double coverage     = static_cast<double>(total);

  // Accuracy: fraction of non-late observations, clipped to [0,1]
  double accuracy = std::max(0.0, 1.0 - late_ratio);

  // Confidence: grows with observations, saturates at HISTORY_DEPTH
  double conf = std::log2(coverage + 1.0) / std::log2(static_cast<double>(HISTORY_DEPTH) + 1.0);
  conf = std::min(1.0, std::max(0.0, conf));

  // Coverage term: log-scaled (diminishing returns) and gated by confidence
  double coverage_term = COVERAGE_WEIGHT * std::log2(coverage + 1.0) * conf;

  // Timeliness term: reward early hits strongly, amplified when accuracy is high
  double timely_term = TIMELINESS_WEIGHT * timely_ratio * accuracy * conf;

  // Small accuracy bonus for very reliable deltas
  double accuracy_bonus = 0.5 * accuracy * conf;

  // Late penalty: penalize late observations, but dampen as coverage grows
  double late_term = ACCURACY_WEIGHT * late_ratio / std::sqrt(coverage + 1.0);

  // Combine: prefer widely-observed, early, and reliable deltas while penalizing late ones
  return coverage_term + timely_term + accuracy_bonus - late_term;
}
// EVOLVE-BLOCK-END

void berti::add_history(pc_entry& entry, champsim::block_number block, uint64_t cycle)
{
  int depth = std::min(HISTORY_DEPTH, 16);
  entry.history[static_cast<std::size_t>(entry.history_head)] = {block, cycle};
  entry.history_head = (entry.history_head + 1) % depth;
  if (entry.history_size < depth)
    entry.history_size++;
}

int berti::best_delta(const pc_entry& entry)
{
  double best_score = -1.0;
  int best_d = 0;

  for (int d = -MAX_DELTA; d <= MAX_DELTA; d++) {
    if (d == 0)
      continue;
    auto idx = static_cast<std::size_t>(d + MAX_DELTA);
    const auto& ds = entry.deltas[idx];
    if (ds.count < MIN_CONFIDENCE)
      continue;
    double score = composite_score(ds.timely, ds.late, ds.count);
    if (score > best_score) {
      best_score = score;
      best_d = d;
    }
  }
  return best_d;
}

void berti::record_pending(champsim::block_number block, uint64_t cycle)
{
  std::size_t oldest_idx = 0;
  uint64_t oldest_cycle = UINT64_MAX;
  for (std::size_t i = 0; i < PENDING_SIZE; i++) {
    if (!pending[i].valid) {
      pending[i] = {block, cycle, true};
      return;
    }
    if (pending[i].issue_cycle < oldest_cycle) {
      oldest_cycle = pending[i].issue_cycle;
      oldest_idx = i;
    }
  }
  pending[oldest_idx] = {block, cycle, true};
}

void berti::prefetcher_initialize()
{
  current_cycle = 0;
  pending.fill({});
}

